def tee_generator(gen, n=2):
    import itertools
    return itertools.tee(gen, n)

g1, g2 = tee_generator(x**2 for x in range(5))
print(list(g1))  # [0, 1, 4, 9, 16]
print(list(g2))  # [0, 1, 4, 9, 16]

# Encadenamiento de generators
def cuadrados(n):
    yield from (x**2 for x in range(n))

def filtrar_pares(gen):
    for x in gen:
        if x % 2 == 0:
            yield x

resultado = list(filtrar_pares(cuadrados(10)))
print(resultado)  # [0, 4, 16, 36, 64]

from typing import Generator, Iterator

def leer_chunks(texto: str, n: int) -> Generator[str, None, None]:
    """Divide un texto en chunks de n caracteres."""
    for i in range(0, len(texto), n):
        yield texto[i:i+n]

for chunk in leer_chunks("abcdefghij", 3):
    print(chunk)  # abc, def, ghi, j

def paginar(items: list, pagina: int) -> Iterator:
    """Generator que paginaea una lista."""
    for i in range(0, len(items), pagina):
        yield items[i:i+pagina]

for pagina in paginar(list(range(10)), 3):
    print(pagina)

def contar_hasta(limite: int):
    """Generator que cuenta de 1 a limite."""
    n = 1
    while n <= limite:
        yield n
        n += 1

for num in contar_hasta(5):
    print(num, end=" ")  # 1 2 3 4 5

