public class Block
{
    private static Dictionary<char, int> typeCounters = new Dictionary<char, int>();

    public string Id { get; }

    public Block(char type)
    {
        if (!typeCounters.ContainsKey(type))
        {
            typeCounters[type] = 1;
        }
