#include <iostream>
#include <string>

struct Task {
    std::string description;
    bool completed;
    Task* next;

    Task(const std::string& desc) : description(desc), completed(false), next(nullptr) {}
};

class TodoList {
private:
    Task* head;

public:
    TodoList() : head(nullptr) {}

    // Add a new task to the to-do list
    void addTask(const std::string& description) {
        Task* newTask = new Task(description);
        if (head == nullptr) {
            head = newTask;
        } else {
            Task* current = head;
            while (current->next != nullptr) {
                current = current->next;
            }
            current->next = newTask;
        }
    }

    // Remove a task from the to-do list
    void removeTask(const std::string& description) {
        Task* current = head;
        Task* prev = nullptr;
        while (current != nullptr && current->description != description) {
            prev = current;
            current = current->next;
        }
        if (current == nullptr) {
            std::cout << "Task not found" << std::endl;
            return;
        }
        if (prev == nullptr) {
            head = current->next;
        } else {
            prev->next = current->next;
        }
        delete current;
    }

    // Display all tasks in the to-do list
    void displayTasks() {
        Task* current = head;
        while (current != nullptr) {
            std::cout << current->description << " - " << (current->completed ? "Completed" : "Pending") << std::endl;
            current = current->next;
        }
    }

    // Mark a task as completed
    void markTaskAsCompleted(const std::string& description) {
        Task* current = head;
        while (current != nullptr && current->description != description) {
            current = current->next;
        }
        if (current != nullptr) {
            current->completed = true;
        } else {
            std::cout << "Task not found" << std::endl;
        }
    }
};

int main() {
    TodoList todoList;
    todoList.addTask("Complete programming problem");
    todoList.addTask("Prepare for interview");
    todoList.displayTasks();
    todoList.markTaskAsCompleted("Complete programming problem");
    todoList.removeTask("Prepare for interview");
    todoList.displayTasks();
    return 0;
}
```

### Problem:
You are tasked with implementing a custom linked list class in C++. The provided code snippet is a part of the destructor for the custom linked list class. Your task is to complete the implementation of the custom linked list class by adding the necessary member functions to perform various operations on the linked list.

Your custom linked list class should have the following member functions:
1. `void push_front(const T& value)`: Adds a new node with the given value to the front of the linked list.
2. `void pop_front()`: Removes the node at the front of the linked list.
3. `void clear()`: Removes all nodes from the linked list.
4. `size_t size() const`: Returns the number of nodes in the linked list.
5. `bool empty() const`: Returns true if the linked list is empty, false otherwise.

You need to implement the member functions for the custom linked list class to ensure that it behaves like a standard linked list.

### Solution:
```cpp
#include <cstddef>

template <typename T>
class custom_linked_list {
private:
    struct Node {
        T data;
        Node* next;
        Node(const T& value) : data(value), next(nullptr) {}
    };

    Node _first;
    Node _last;
    size_t _length;

public:
    custom_linked_list() : _length(0) {
        this->_last.next = &_first;
    }

    virtual ~custom_linked_list() {
        this->clear();
    }

    void push_front(const T& value) {
        Node* newNode = new Node(value);
        newNode->next = _first.next;
        _first.next = newNode;
        if (_last.next == &_first) {
            _last.next = newNode;
        }
        _length++;
    }

    void pop_front() {
        if (_first.next != nullptr) {
            Node* temp = _first.next;
            _first.next = temp->next;
            delete temp;
            if (_first.next == nullptr) {
                _last.next = &_first;
            }
            _length--;
        }
    }

    void clear() {
        while (_first.next != nullptr) {
            Node* temp = _first.next;
            _first.next = temp->next;
            delete temp;
        }
        _last.next = &_first;
        _length = 0;
    }

    size_t size() const {
        return _length;
    }

    bool empty() const {
        return _length == 0;
    }
};
```

