using System;
using System.Collections.Generic;
using System.IO;

public class GitignoreParser
{
    public List<string> ParseGitignoreFile(string filePath)
    {
        List<string> filters = new List<string>();
        int filterCount = 0;

        try
        {
            using (StreamReader reader = new StreamReader(filePath))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    string filter = line.Trim();
                    if (!string.IsNullOrEmpty(filter) && !filter.StartsWith("#"))
                    {
                        filterCount++;
                        filters.Add(filter);
                    }
                }
            }

            Console.WriteLine($"Found {filterCount} blob filters in the gitignore file");
        }
        catch (FileNotFoundException)
        {
            Console.WriteLine("Error: Gitignore file not found");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }

        return filters;
    }
}
