using Microsoft.Bot.Builder;
using Microsoft.Bot.Schema;
using Microsoft.Extensions.Logging;
using System;
using System.Threading;
using System.Threading.Tasks;

namespace GuidedSearchBot.Bots
{
    public class ActivityLoggerMiddleware : IMiddleware
    {
        private readonly ILogger _logger;
        private readonly LogLevel _minLogLevel;

        public ActivityLoggerMiddleware(ILogger<ActivityLoggerMiddleware> logger, LogLevel minLogLevel = LogLevel.Information)
        {
            _logger = logger;
            _minLogLevel = minLogLevel;
        }

        public async Task OnTurnAsync(ITurnContext turnContext, NextDelegate next, CancellationToken cancellationToken = default)
        {
            if (turnContext.Activity != null)
            {
                if (turnContext.Activity.Type == ActivityTypes.Message)
                {
                    LogActivity(turnContext.Activity);
                }
            }

            await next(cancellationToken).ConfigureAwait(false);
        }

        private void LogActivity(Activity activity)
        {
            if (activity.Timestamp != null && activity.Type != null && activity.Text != null)
            {
                if (_minLogLevel <= LogLevel.Information)
                {
                    _logger.LogInformation($"[{activity.Timestamp}] {activity.Type}: {activity.Text}");
                }
            }
        }
    }
}
```

