public class SinglePointCrossover : ICrossover
{
    protected Random RandomNumberGenerator { get; set; } = new();
    public int ParentsCount { get; } = 2;
    public int ChildrenCount { get; } = 2;
    public int BitAlign { get; set; } = 1;

    public IGenotype[] Cross(IGenotype[] parents)
    {
        if (parents.Length != ParentsCount)
        {
            throw new ArgumentException("Invalid number of parent genotypes");
        }

        if (parents[0].Length != parents[1].Length)
        {
            throw new ArgumentException("Parent genotypes must have the same length");
        }

        int crossoverPoint = RandomNumberGenerator.Next(1, parents[0].Length - BitAlign);

        IGenotype child1 = new Genotype(parents[0].Substring(0, crossoverPoint) + parents[1].Substring(crossoverPoint));
        IGenotype child2 = new Genotype(parents[1].Substring(0, crossoverPoint) + parents[0].Substring(crossoverPoint));

        return new IGenotype[] { child1, child2 };
    }
}
```

