You are tasked with implementing a class for managing a linked list of integers. The class, named `LinkedList`, should support various operations on the linked list, including insertion, deletion, and searching for elements.

Your task is to implement the `LinkedList` class with the following specifications:

1. The class should have a private member variable `ensemble` that points to the head of the linked list.
2. The linked list nodes should be implemented using a nested class named `Node`, which has two public member variables: `value` to store the integer value and `next` to point to the next node in the list.
3. The `LinkedList` class should have the following public member functions:
   - `LinkedList()`: A default constructor that initializes the `ensemble` pointer to `nullptr`.
   - `void insert(int value)`: Inserts a new node with the given value at the beginning of the linked list.
   - `bool search(int value)`: Searches for the given value in the linked list and returns true if found, otherwise returns false.
   - `void remove(int value)`: Removes the first occurrence of the given value from the linked list if it exists.

You are required to implement the member functions of the `LinkedList` class to fulfill the given specifications.

### Solution:
```cpp
#include <iostream>

class LinkedList {
private:
    struct Node {
        int value;
        Node* next;
        Node(int val) : value(val), next(nullptr) {}
    };

    Node* ensemble;

public:
    LinkedList() : ensemble(nullptr) {}

    void insert(int value) {
        Node* newNode = new Node(value);
        newNode->next = ensemble;
        ensemble = newNode;
    }

    bool search(int value) {
        Node* current = ensemble;
        while (current != nullptr) {
            if (current->value == value) {
                return true;
            }
            current = current->next;
        }
        return false;
    }

    void remove(int value) {
        Node* current = ensemble;
        Node* prev = nullptr;

        while (current != nullptr && current->value != value) {
            prev = current;
            current = current->next;
        }

        if (current == nullptr) {
            return;  // Value not found
        }

        if (prev == nullptr) {
            ensemble = current->next;
        } else {
            prev->next = current->next;
        }

        delete current;
    }
};

int main() {
    LinkedList list;
    list.insert(10);
    list.insert(20);
    list.insert(30);

    std::cout << "Search 20: " << (list.search(20) ? "Found" : "Not found") << std::endl;
    std::cout << "Search 40: " << (list.search(40) ? "Found" : "Not found") << std::endl;

    list.remove(20);
    std::cout << "Search 20 after removal: " << (list.search(20) ? "Found" : "Not found") << std::endl;

    return 0;
}
```

