### Problem:
You are tasked with implementing a doubly linked list data structure in C++. The list should support the following operations:
1. `pushTail(int value)`: Add a new node with the given value to the end of the list.
2. `insert(int index, int value)`: Insert a new node with the given value at the specified index in the list. If the index is out of bounds, the value should be added to the end of the list.
3. `swap(int index1, int index2)`: Swap the values at the specified indices in the list.

You need to implement the doubly linked list class and the mentioned operations. After implementing the class, you should demonstrate its functionality by performing the following operations:
1. Add a node with value 0 to the end of the list.
2. Insert a node with value 4 at index 3 in the list.
3. Print the list after the above operations.
4. Swap the values at indices 2 and 5 in the list.
5. Print the list after the swap operation.

Your implementation should correctly handle all the mentioned operations and produce the expected output.

### Solution:
```cpp
#include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node* prev;
    Node* next;
    Node(int value) : data(value), prev(nullptr), next(nullptr) {}
};

class DoublyLinkedList {
private:
    Node* head;
    Node* tail;
public:
    DoublyLinkedList() : head(nullptr), tail(nullptr) {}

    void pushTail(int value) {
        Node* newNode = new Node(value);
        if (head == nullptr) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
        }
    }

    void insert(int index, int value) {
        Node* newNode = new Node(value);
        if (head == nullptr || index <= 0) {
            pushTail(value);
            return;
        }
        Node* current = head;
        for (int i = 0; i < index - 1; i++) {
            if (current->next != nullptr) {
                current = current->next;
            } else {
                break;
            }
        }
        newNode->next = current->next;
        newNode->prev = current;
        if (current->next != nullptr) {
            current->next->prev = newNode;
        } else {
            tail = newNode;
        }
        current->next = newNode;
    }

    void swap(int index1, int index2) {
        if (index1 == index2) {
            return;
        }
        Node* node1 = getNodeAtIndex(index1);
        Node* node2 = getNodeAtIndex(index2);
        if (node1 == nullptr || node2 == nullptr) {
            return;
        }
        int temp = node1->data;
        node1->data = node2->data;
        node2->data = temp;
    }

    Node* getNodeAtIndex(int index) {
        if (head == nullptr || index < 0) {
            return nullptr;
        }
        Node* current = head;
        for (int i = 0; i < index; i++) {
            if (current->next != nullptr) {
                current = current->next;
            } else {
                return nullptr;
            }
        }
        return current;
    }

    friend ostream& operator<<(ostream& os, const DoublyLinkedList& list) {
        Node* current = list.head;
        while (current != nullptr) {
            os << current->data << " ";
            current = current->next;
        }
        return os;
    }
};

int main() {
    DoublyLinkedList list;
    list.pushTail(0);
    list.insert(3, 4);
    cout << list << endl;
    list.swap(2, 5);
    cout << list << endl;

    return EXIT_SUCCESS;
}
```

The `DoublyLinkedList` class is implemented with the required operations `pushTail`, `insert`, and `swap`. The `main` function demonstrates the usage of these operations and prints the list after each operation. The output of the program should match the expected output based on the provided code snippet.

