### Solution:
```rust
use std::{iter::{FilterMap, FusedIterator}, slice::IterMut};

#[doc(hidden)]
#[derive(Debug)]
pub struct Iter<'a, T: 'a>(FilterMap<IterMut<'a, Option<T>>, fn(&'a mut Option<T>) -> Option<T>>);

impl<'a, T: 'a> Iterator for Iter<'a, T> {
    type Item = T;

    fn next(&mut self) -> Option<Self::Item> {
        self.0.next()
    }
}

impl<'a, T: 'a> Iter<'a, T> {
    fn new(slice: &'a mut [Option<T>]) -> Self {
        fn filter_none<T>(opt: &'_ mut Option<T>) -> Option<T> {
            opt.take()
        }
        Iter(slice.iter_mut().filter_map(filter_none))
    }
}

impl<'a, T: 'a> IntoIterator for &'a mut [Option<T>] {
    type Item = T;
    type IntoIter = Iter<'a, T>;

    fn into_iter(self) -> Self::IntoIter {
        Iter::new(self)
    }
}

impl<'a, T: 'a> FusedIterator for Iter<'a, T> {}
